{
  "missing_information": [
    {
      "category": "Reservation Channel",
      "gap": "It is unclear how the organizer checks availability and makes the reservation — whether through a calendar system, a dedicated room booking tool, a manual sign-up sheet, or by contacting an administrator.",
      "why_it_matters": "The channel determines which systems are involved and where automation can be applied, such as API integrations with calendar platforms."
    },
    {
      "category": "Eligibility and Authorization",
      "gap": "There is no information about whether any approval or authorization is required before a room can be confirmed, or whether all employees can reserve rooms freely.",
      "why_it_matters": "An approval step adds a decision node to the process and may require routing logic, affecting automation complexity."
    },
    {
      "category": "Conflict Resolution",
      "gap": "The workflow does not describe what happens when the desired room or time slot is already booked — whether the organizer selects an alternative or escalates to an administrator.",
      "why_it_matters": "Conflict handling is a key branching point that must be modeled to ensure the process is complete and automatable."
    },
    {
      "category": "Participant Notification",
      "gap": "The method by which room information is shared with participants is not specified — whether via calendar invite, email, messaging platform, or another channel.",
      "why_it_matters": "The notification mechanism determines whether this step can be automated and integrated with existing communication tools."
    },
    {
      "category": "Reservation Lifecycle",
      "gap": "There is no mention of post-reservation activities such as modification, cancellation, reminders, or check-in confirmation on the day of the meeting.",
      "why_it_matters": "Lifecycle events are common automation targets and omitting them leaves the process model incomplete."
    },
    {
      "category": "Resource Attributes",
      "gap": "No criteria are defined for selecting a room, such as required capacity, equipment needs, location, or accessibility requirements.",
      "why_it_matters": "Selection criteria determine whether room matching can be automated and what data inputs the system needs to support decision-making."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What system or method does the organizer use to check room availability and submit the reservation — for example, a calendar application, a dedicated booking platform, or a manual process?",
      "targets": ["Reservation Channel"]
    },
    {
      "id": "Q2",
      "question": "Is any form of approval required after a reservation request is submitted, and if so, who grants that approval and under what conditions?",
      "targets": ["Eligibility and Authorization"]
    },
    {
      "id": "Q3",
      "question": "What happens when the requested room or time slot is unavailable — does the organizer manually search for alternatives, or does the system suggest them automatically?",
      "targets": ["Conflict Resolution"]
    },
    {
      "id": "Q4",
      "question": "Through which channel is the room information communicated to participants once the reservation is confirmed — for example, a calendar invite, an email notification, or a messaging tool?",
      "targets": ["Participant Notification"]
    },
    {
      "id": "Q5",
      "question": "Are there defined criteria the organizer must consider when selecting a room, such as minimum capacity, required equipment, or physical location?",
      "targets": ["Resource Attributes"]
    },
    {
      "id": "Q6",
      "question": "Does the process include any post-confirmation steps such as sending reminders before the meeting, allowing modifications or cancellations, or requiring a check-in on the day of the meeting?",
      "targets": ["Reservation Lifecycle"]
    }
  ]
}
